/**
 * 化合物番号（18d）と、単位の付いた数値（18 d ＝ 18 日）の区別.
 *
 * 「18d」 is the same shape either way, and the checklist wants opposite things
 * of them: a value wants a space before its unit, a compound label must stay
 * closed up. Only the document as a whole can tell them apart, so this runs once
 * over every paragraph and hands the rules a set of the tokens that are labels.
 *
 * Three signals are trusted, and nothing else:
 *
 * - **The word says so.** 「化合物 18d」 / "compound 18d" names it outright.
 * - **It has siblings.** A paper that writes 18a and 18d is numbering a series;
 *   no one reports a duration as 18 a.
 * - **It is written as a range.** 「1a–f」 introduces the whole series at once,
 *   which is how a paper with six analogues usually says it.
 *
 * A lone 「18d」 with none of them stays ambiguous, and the caller keeps the
 * finding but asks rather than rewrites — see `missingSpaceRule`.
 */

/**
 * What may follow a compound label without the label ending there.
 *
 * A reduced or oxidised species carries its charge right after the number —
 * 「1b2–」 is the dianion of **1b**, not a compound called 1b2. Word writes the
 * charge as a superscript, but `paragraph.text` hands it over as ordinary
 * characters, so to the text it looks like one run of alphanumerics and a plain
 * 「直後が英数字でないこと」 test throws the whole label away.
 *
 * Only 「数字＋符号」 needs spelling out. A charge written 「1a–」 or 「1a•–」 already
 * ends the label, because neither the dash nor the dot is alphanumeric.
 */
export const CHARGE_AHEAD = "(?=\\d{1,2}\\s*[–—−+])";

/** A compound label ends where letters and digits stop — or where a charge starts. */
export const LABEL_END = `(?:(?![A-Za-z0-9])|${CHARGE_AHEAD})`;

/**
 * Number followed by a single lower-case letter. The leading `.` in the
 * lookbehind keeps the "5d" of 「18.5d」 out: a decimal is a measurement, and
 * compound numbers are integers.
 */
const LABEL = new RegExp(`(?<![A-Za-z0-9.])(\\d{1,4})([a-z])${LABEL_END}`, "gu");

/**
 * A whole series written as a range: 「1a–f」「1a–1f」「2a-2d」.
 *
 * A second number is allowed but must repeat the first — 「1a–2b」 is two labels
 * with a dash between them, not one range, and expanding it would invent
 * compounds that do not exist.
 */
const LABEL_RANGE = new RegExp(
  `(?<![A-Za-z0-9.])(\\d{1,4})([a-z])\\s*[–—−-]\\s*(\\d{1,4})?([a-z])${LABEL_END}`,
  "gu",
);

/**
 * The ranges written out in one paragraph, as spans.
 *
 * 「1a–f」 names six compounds but is one thing on the page, and the emphasis
 * belongs to all of it: bolding only the 「1a」 gives **1a**–f, which reads as a
 * different claim. `compoundLabels` above expands ranges into their members and
 * so loses the span, hence this second view of the same pattern.
 */
export function labelRanges(text: string): Array<{ start: number; text: string; base: string }> {
  const spans: Array<{ start: number; text: string; base: string }> = [];
  LABEL_RANGE.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = LABEL_RANGE.exec(text)) !== null) {
    spans.push({ start: m.index, text: m[0], base: `${m[1]}${m[2]}` });
  }
  return spans;
}

// --- 図表番号は化合物番号ではない ------------------------------------------
//
// 「Figure 21a」 の 21a は図の 3 枚目であって化合物ではない。太字にもなりうるし、
// 系列（21a・21b・21c）にも見えるので、形だけでは化合物番号と区別が付かない。
// 手前のラベルだけが根拠になる。実機で `(Figure 21a)` の 3 つが一覧に並んだ。

/** 数字の直前にこれがあれば図表番号。「Fig. 1」「表 2」「Scheme 3」。 */
const FIGURE_LABEL =
  /(?:Fig(?:ures?|s?)?\.?|Tables?|Schemes?|Charts?|Eq(?:uations?|ns?)?\.?|Entry|Entries|Refs?\.?|図|表|式|スキーム|チャート)\s*$/iu;

/** 「Figures 1 and 2」「図 1、2」 — the label reaches past the connector to the next number. */
const CONNECTOR = /^[\s,、and&+\-–—]*$/iu;

/** How far back to look for a figure label. Long enough for "Figures 1 and ". */
const FIGURE_LOOKBACK = 28;

/**
 * True when the number at `index` is a figure or table number.
 *
 * Reaches past one connector, so the 「2」 of 「Figures 1 and 2」 is covered as
 * well as the 「1」 — a list of figures wears the label once.
 */
export function isFigureNumber(text: string, index: number): boolean {
  const before = text.slice(Math.max(0, index - FIGURE_LOOKBACK), index);
  if (FIGURE_LABEL.test(before)) return true;
  const viaConnector = /(\d+)([\s,、and&+\-–—]*)$/iu.exec(before);
  if (!viaConnector || !CONNECTOR.test(viaConnector[2]!)) return false;
  return FIGURE_LABEL.test(before.slice(0, before.length - viaConnector[0].length));
}

/** 「化合物 18d」「compound 18d」「compds 3a」 — the label named as such. */
const INTRODUCED = /(?:化合物|compounds?|compds?\.?)\s*$/iu;

/** How far back to look for that word. Long enough for "compounds ". */
const LOOKBACK = 12;

/** The letters an `a`–`f` range covers, or empty when it runs backwards. */
function letterSpan(from: string, to: string): string[] {
  const start = from.charCodeAt(0);
  const end = to.charCodeAt(0);
  if (end <= start) return [];
  const letters: string[] = [];
  for (let code = start; code <= end; code += 1) letters.push(String.fromCharCode(code));
  return letters;
}

/**
 * Every 「数字＋英小文字」 token in the document that is a compound label.
 *
 * Tokens whose letter could never be a unit (18f, 1x) are labels as far as any
 * caller is concerned, but they are only reported here when a signal says so —
 * the rules that consult this set are the ones that would otherwise mistake a
 * label for a unit, and those letters are not units to begin with.
 */
export function compoundLabels(paragraphs: readonly string[]): Set<string> {
  /** stem → the letters seen after it, e.g. "18" → {a, b, d}. */
  const series = new Map<string, Set<string>>();
  const named = new Set<string>();

  const record = (stem: string, letter: string): void => {
    if (!series.has(stem)) series.set(stem, new Set());
    series.get(stem)!.add(letter);
  };

  for (const text of paragraphs) {
    LABEL.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = LABEL.exec(text)) !== null) {
      const [token, stem, letter] = m as unknown as [string, string, string];
      record(stem, letter);
      const before = text.slice(Math.max(0, m.index - LOOKBACK), m.index);
      if (INTRODUCED.test(before)) named.add(token);
    }

    LABEL_RANGE.lastIndex = 0;
    while ((m = LABEL_RANGE.exec(text)) !== null) {
      const [, stem, first, secondStem, last] = m as unknown as [string, string, string, string | undefined, string];
      if (secondStem !== undefined && secondStem !== stem) continue;
      for (const letter of letterSpan(first, last)) record(stem, letter);
    }
  }

  const labels = new Set(named);
  for (const [stem, letters] of series) {
    if (letters.size < 2) continue;
    for (const letter of letters) labels.add(`${stem}${letter}`);
  }
  return labels;
}
