/**
 * Small text primitives shared by the rules: character classes, sentence
 * splitting, and language detection. Kept separate so each rule module stays
 * about its own checklist item.
 */

/** Character-class fragments, reused inside `RegExp` sources. */
export const CLASS = Object.freeze({
  /** Hiragana, katakana, CJK ideographs, and full-width forms. */
  cjk: "\\u3040-\\u30FF\\u3400-\\u4DBF\\u4E00-\\u9FFF\\uFF00-\\uFFEF\\u3000-\\u303F",
  greek: "\\u0370-\\u03FF\\u1F00-\\u1FFF",
  /** Sentence terminators in both scripts. */
  terminator: "。．\\.!?！？",
});

const CJK_RE = new RegExp(`[${CLASS.cjk}]`, "u");
const CJK_GLOBAL_RE = new RegExp(`[${CLASS.cjk}]`, "gu");

/** True when the string contains at least one Japanese character. */
export function hasCJK(text: string): boolean {
  return CJK_RE.test(text);
}

/** Fraction of characters that are Japanese, ignoring whitespace. */
export function cjkRatio(text: string): number {
  const dense = text.replace(/\s+/g, "");
  if (dense.length === 0) return 0;
  return (dense.match(CJK_GLOBAL_RE)?.length ?? 0) / dense.length;
}

/**
 * A sentence together with where it started in the source paragraph.
 * The terminator is kept as part of the sentence.
 */
export interface Sentence {
  readonly text: string;
  readonly start: number;
}

const SENTENCE_END = new RegExp(`[${CLASS.terminator}]`, "u");

/**
 * Splits a paragraph into sentences.
 *
 * A bare "." only ends a sentence when it is not part of an abbreviation or a
 * decimal number, so "J. Am. Chem. Soc." and "1.5 mL" stay in one piece. The
 * full-width terminators 。．! ? never have that ambiguity in practice.
 */
export function splitSentences(paragraph: string): Sentence[] {
  const sentences: Sentence[] = [];
  let start = 0;

  for (let i = 0; i < paragraph.length; i += 1) {
    const ch = paragraph[i]!;
    if (!SENTENCE_END.test(ch)) continue;

    if ((ch === "." || ch === "．") && !endsSentence(paragraph, i)) continue;

    // Absorb a closing bracket or quote that belongs to this sentence.
    let end = i + 1;
    while (end < paragraph.length && /[)）」』】\]”’"']/u.test(paragraph[end]!)) end += 1;

    const text = paragraph.slice(start, end);
    if (text.trim().length > 0) sentences.push({ text, start });
    start = end;
  }

  const tail = paragraph.slice(start);
  if (tail.trim().length > 0) sentences.push({ text: tail, start });
  return sentences;
}

/** Heuristic for whether the "." at `i` terminates a sentence. */
function endsSentence(text: string, i: number): boolean {
  const before = text[i - 1] ?? "";
  const after = text[i + 1] ?? "";

  // Decimal point: 1.5
  if (/\d/u.test(before) && /\d/u.test(after)) return false;

  // Abbreviation: a single capital or a short capitalised token followed by a
  // space and another capitalised token — "J. Am.", "et al.", "Fig. 1".
  const token = /([A-Za-z]+)\.$/u.exec(text.slice(0, i + 1))?.[1] ?? "";
  if (token.length > 0 && token.length <= 4 && /^[A-Z]/u.test(token) && /^\s*[A-Z0-9(]/u.test(after ? text.slice(i + 1) : "")) {
    return false;
  }
  if (/\b(et al|vs|cf|e\.g|i\.e|approx|ca|eq|ref)\.$/iu.test(text.slice(0, i + 1))) return false;

  return true;
}

/**
 * Runs a global regex and yields each match with its index, guarding against
 * the zero-length-match infinite loop.
 */
export function* matchAll(re: RegExp, text: string): Generator<RegExpExecArray> {
  const cursor = new RegExp(re.source, re.flags.includes("g") ? re.flags : `${re.flags}g`);
  cursor.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = cursor.exec(text)) !== null) {
    yield m;
    if (m[0].length === 0) cursor.lastIndex += 1;
  }
}

/** Escapes a literal string for use inside a `RegExp`. */
export function escapeRegExp(literal: string): string {
  return literal.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
}
