/**
 * 2-(3) 参考文献 — 黄マーカー.
 *
 * 引用位置 (和文は句読点の前、英文は後), 雑誌略称, 引用スタイルの統一.
 * 著者名の姓名順や太字・斜体の位置は書誌データの意味を知らないと判定できないため、
 * ここでは「同じ書き方で揃っているか」だけを見る。
 */
import { JOURNAL_ABBREV } from "../dict.ts";
import { citedNumbers } from "../inventory.ts";
import { bibliographyParagraphs, bodyCitations, parseBibliography } from "../references.ts";
import type { DocumentRule, Finding, ParagraphRule } from "../types.ts";
import { finding } from "../types.ts";
import { escapeRegExp, hasCJK, matchAll } from "../text.ts";
import { dictionaryRule, arrowMessage } from "./dictRule.ts";

/** A bracketed citation such as [1], [2,3], [4–6]. */
const CITATION = /\[\s*\d+(?:\s*[,–\-]\s*\d+)*\s*\]/u;
const CITATION_SOURCE = CITATION.source;

/**
 * 文中に引用を入れる位置。
 *
 *   日本語：「・・・であることが知られている[1]．」※句読点の前
 *   英文  ：「··· has been reported.[1]」          ※カンマやピリオドの後
 *
 * The rule reads each paragraph's own script rather than the document's, so a
 * bilingual manuscript is judged sentence by sentence.
 */
const JA_CITATION_AFTER_PUNCT = new RegExp(`([。．])\\s*(${CITATION_SOURCE})`, "gu");
const EN_CITATION_BEFORE_PUNCT = new RegExp(`(${CITATION_SOURCE})\\s*([.,])`, "gu");

export const citationPositionRule: ParagraphRule = {
  id: "citation-position",
  category: "reference",
  title: "引用番号と句読点の前後",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];

    if (hasCJK(text)) {
      for (const m of matchAll(JA_CITATION_AFTER_PUNCT, text)) {
        const replacement = `${m[2]}${m[1]}`;
        found.push(
          finding(citationPositionRule, {
            severity: "fix",
            paragraphIndex: index,
            start: m.index,
            matched: m[0],
            replacement,
            message: `和文では引用番号は句読点の前：「${m[0]}」→「${replacement}」`,
          }),
        );
      }
    } else {
      for (const m of matchAll(EN_CITATION_BEFORE_PUNCT, text)) {
        const replacement = `${m[2]}${m[1]}`;
        found.push(
          finding(citationPositionRule, {
            severity: "fix",
            paragraphIndex: index,
            start: m.index,
            matched: m[0],
            replacement,
            message: `英文では引用番号はピリオド・カンマの後：「${m[0]}」→「${replacement}」`,
          }),
        );
      }
    }

    return found;
  },
};

/** 雑誌名の略称は正しいものを用いること。 */
export const journalAbbrevRule = dictionaryRule({
  id: "journal-abbrev",
  category: "reference",
  title: "雑誌略称",
  entries: JOURNAL_ABBREV,
  message: arrowMessage("雑誌略称"),
});

/**
 * 雑誌略称や名称が途中で変わっているものは特に要注意.
 *
 * The rule used to group by the first two tokens, which is not how journal names
 * work. 「J. Phys. Chem. A」 and 「J. Phys. Chem. C」 are two different journals, and
 * so are 「J. Chem. Phys.」 and 「J. Chem. Soc.」 — grouping either pair together and
 * offering to "unify" them is worse than saying nothing.
 *
 * What is actually decidable from the text is narrower, and this is now all of it:
 *
 * - **The same name punctuated two ways.** 「J Am Chem Soc」 / 「J. Am. Chem. Soc.」
 *   are the same characters once periods and spaces are taken out.
 * - **A dropped edition suffix.** 「Angew. Chem. Int. Ed. Engl.」 lost its 「Engl.」
 *   in 1998, and the checklist calls that case out by name.
 *
 * Everything else — a differing token anywhere, and in particular a trailing
 * section letter (A/B/C, as in J. Phys. Chem. and Phys. Rev.) — is left alone.
 */
const JOURNAL_LIKE = /\b(?:[A-Z][A-Za-z]*\.\s*){2,}(?:[A-Z][A-Za-z]*\.?)/gu;

/**
 * Trailing tokens that are an edition marker rather than part of the title.
 *
 * A single letter is deliberately absent: that is a section (J. Mater. Chem. A),
 * which makes the name a *different* journal, not the same one spelled loosely.
 */
const EDITION_SUFFIXES: ReadonlySet<string> = new Set(["engl"]);

/**
 * The key two spellings share when they are the same journal: lower-cased, with
 * periods and spaces removed and any edition suffix dropped.
 */
function journalKey(name: string): string {
  const tokens = name.split(/\s+/u).filter((t) => t.length > 0);
  while (tokens.length > 2 && EDITION_SUFFIXES.has(tokens[tokens.length - 1]!.replace(/\./gu, "").toLowerCase())) {
    tokens.pop();
  }
  return tokens.join("").replace(/\./gu, "").toLowerCase();
}

export const journalConsistencyRule: DocumentRule = {
  id: "journal-consistency",
  category: "reference",
  title: "雑誌略称の揺れ",
  kind: "document",
  run(paragraphs): Finding[] {
    interface Hit {
      readonly paragraphIndex: number;
      readonly start: number;
      readonly text: string;
    }
    const hits: Hit[] = [];
    paragraphs.forEach((text, paragraphIndex) => {
      for (const m of matchAll(JOURNAL_LIKE, text)) {
        hits.push({ paragraphIndex, start: m.index, text: m[0].trim() });
      }
    });

    const journals = new Map<string, Map<string, Hit[]>>();
    for (const hit of hits) {
      const key = journalKey(hit.text);
      if (key.length === 0) continue;
      if (!journals.has(key)) journals.set(key, new Map());
      const forms = journals.get(key)!;
      if (!forms.has(hit.text)) forms.set(hit.text, []);
      forms.get(hit.text)!.push(hit);
    }

    const found: Finding[] = [];
    for (const forms of journals.values()) {
      if (forms.size < 2) continue;
      const sorted = [...forms.entries()].sort((a, b) => b[1].length - a[1].length);
      const preferred = sorted[0]![0];
      for (const [form, occurrences] of sorted.slice(1)) {
        for (const hit of occurrences) {
          found.push(
            finding(journalConsistencyRule, {
              severity: "confirm",
              paragraphIndex: hit.paragraphIndex,
              start: hit.start,
              matched: hit.text,
              replacement: preferred,
              message: `同じ雑誌が 2 通りに書かれています：「${form}」と「${preferred}」。掲載年による改称でなければ統一してください。`,
            }),
          );
        }
      }
    }
    return found;
  },
};

/** 引用文献のスタイルを統一すること — bracket shape used for citation markers. */
const CITATION_STYLES: ReadonlyArray<{ name: string; re: RegExp }> = [
  { name: "[1]", re: /\[\s*\d+(?:\s*[,–\-]\s*\d+)*\s*\]/gu },
  { name: "(1)", re: /(?<![A-Za-z0-9])\(\s*\d+(?:\s*[,–\-]\s*\d+)*\s*\)(?![A-Za-z0-9])/gu },
];

export const citationStyleRule: DocumentRule = {
  id: "citation-style",
  category: "reference",
  title: "引用スタイルの統一",
  kind: "document",
  run(paragraphs): Finding[] {
    const counts = CITATION_STYLES.map(({ name, re }) => ({
      name,
      re,
      total: paragraphs.reduce((n, p) => n + [...matchAll(re, p)].length, 0),
    }));
    const used = counts.filter((c) => c.total > 0);
    if (used.length < 2) return [];

    const sorted = [...used].sort((a, b) => b.total - a.total);
    const preferred = sorted[0]!;
    const found: Finding[] = [];
    for (const style of sorted.slice(1)) {
      paragraphs.forEach((text, paragraphIndex) => {
        for (const m of matchAll(style.re, text)) {
          found.push(
            finding(citationStyleRule, {
              severity: "confirm",
              paragraphIndex,
              start: m.index,
              matched: m[0],
              message: `引用の書式が混在しています（${preferred.name} が ${preferred.total} 件、${style.name} が ${style.total} 件）。`,
            }),
          );
        }
      });
    }
    return found;
  },
};

/**
 * 著者名の姓名は逆になっていないか — the two conventions are "Smith, J. A." and
 * "J. A. Smith". Both are fine; using both in one bibliography is not.
 */
// Two traps, both from the same ambiguity — a comma-separated author list looks
// locally like the other convention:
//   "Y. Tanaka, H. Suzuki" contains "Tanaka, H.", which is not surname-first, so
//     a surname preceded by its own initials is excluded (`initialsPrecede`).
//   "Brown, K. Chem. Commun." contains "K. Chem", where the capitalised word is
//     the journal, so a word that is itself an abbreviation is excluded.
const SURNAME_FIRST = /\b([A-Z][a-z]+),\s*([A-Z]\.(?:\s*[A-Z]\.)*)/gu;
const INITIALS_FIRST = /\b([A-Z]\.(?:\s*[A-Z]\.)*)\s+([A-Z][a-z]+)\b(?!\.)/gu;

/** Long enough for the initials and particles of one name: 「P. W. N. M. van der 」. */
const AUTHOR_LOOKBACK = 40;

/**
 * True when the surname at `index` already has its own initials in front of it —
 * so 「…, X.」 after it is the *next* author, not this one's initials.
 *
 * Looking back one initial was not enough. A surname of two or more words puts
 * something else immediately in front of it, and then 「López Navarrete, J.」 in
 * an entry written 「J. T. López Navarrete, J. Casado, …」 reads as surname-first.
 * Sixteen of the ninety-nine references in the user's manuscript were flagged
 * this way, every one of them a compound surname: Ponce Ortiz, Di Motta,
 * van Leeuwen, De Proft, Longuet-Higgins.
 *
 * So the search runs back to whatever separated this author from the last one
 * (a comma or a semicolon, or the start of the entry) and asks whether an
 * initial stands anywhere in between. In 「Smith, J. A.; Jones, B. C.」 nothing
 * does — the semicolon cuts the initials off — and surname-first still reports.
 */
function initialsPrecede(text: string, index: number): boolean {
  const before = text.slice(Math.max(0, index - AUTHOR_LOOKBACK), index);
  const separator = Math.max(before.lastIndexOf(","), before.lastIndexOf(";"));
  return /[A-Z]\./u.test(before.slice(separator + 1));
}

export const authorOrderRule: DocumentRule = {
  id: "author-order",
  category: "reference",
  title: "著者名の姓名順の統一",
  kind: "document",
  run(paragraphs): Finding[] {
    const surnameFirst: Array<{ paragraphIndex: number; start: number; text: string }> = [];
    const initialsFirst: Array<{ paragraphIndex: number; start: number; text: string }> = [];

    paragraphs.forEach((text, paragraphIndex) => {
      for (const m of matchAll(SURNAME_FIRST, text)) {
        if (initialsPrecede(text, m.index)) continue;
        surnameFirst.push({ paragraphIndex, start: m.index, text: m[0] });
      }
      for (const m of matchAll(INITIALS_FIRST, text)) {
        initialsFirst.push({ paragraphIndex, start: m.index, text: m[0] });
      }
    });

    if (surnameFirst.length === 0 || initialsFirst.length === 0) return [];

    const minority = surnameFirst.length < initialsFirst.length ? surnameFirst : initialsFirst;
    const minorityName = surnameFirst.length < initialsFirst.length ? "姓, イニシャル" : "イニシャル 姓";
    const majorityName = minorityName === "姓, イニシャル" ? "イニシャル 姓" : "姓, イニシャル";

    return minority.map((hit) =>
      finding(authorOrderRule, {
        severity: "confirm",
        paragraphIndex: hit.paragraphIndex,
        start: hit.start,
        matched: hit.text,
        message: `著者名の姓名順が混在しています（多数派は「${majorityName}」、ここは「${minorityName}」）。`,
      }),
    );
  },
};

/**
 * 文献リストにあるのに本文が引用していない項目.
 *
 * ［文献］一覧はこれを前から出していたが、一覧を開いた人にしか届かなかった。
 * 引用し忘れは投稿前に必ず直す種類の誤りなので、指摘一覧にも並べる。
 *
 * The finding points at the bibliography entry rather than at the body: there
 * is, by definition, nowhere in the body to point at. Its severity is 情報 —
 * there is no replacement text, and the fix is either to cite the work or to
 * delete the entry, which is the author's call.
 */
export const uncitedReferenceRule: DocumentRule = {
  id: "uncited-reference",
  category: "reference",
  title: "引用されていない文献",
  kind: "document",
  run(paragraphs): Finding[] {
    const entries = parseBibliography(paragraphs);
    if (entries.length === 0) return [];

    const inList = bibliographyParagraphs(entries);
    const cited = new Set<number>();
    for (const hit of bodyCitations(paragraphs, inList)) {
      for (const number of citedNumbers(hit.text)) cited.add(number);
    }

    return entries
      .filter((entry) => !cited.has(entry.number))
      .map((entry) =>
        finding(uncitedReferenceRule, {
          severity: "note",
          paragraphIndex: entry.paragraphIndex,
          start: entry.start,
          matched: entry.marker,
          message: `文献 ${entry.number} は本文のどこからも引用されていません。引用を加えるか、リストから外してください。`,
        }),
      );
  },
};

export const REFERENCE_RULES = [
  citationPositionRule,
  journalAbbrevRule,
  journalConsistencyRule,
  citationStyleRule,
  authorOrderRule,
  uncitedReferenceRule,
];

export { CITATION, escapeRegExp };
