/**
 * 1-(2) 科学的正確さ — 青色マーカー.
 *
 * Most of this checklist section asks whether a claim is *true*, which no rule
 * can answer. 「一般的でない用語・略語は定義すること」 is the exception: whether an
 * abbreviation was ever spelled out is a fact about the text, so it is decidable
 * here.
 */
import { COMMON_ABBREVIATIONS } from "../dict.ts";
import type { DocumentRule, Finding } from "../types.ts";
import { finding } from "../types.ts";
import { matchAll } from "../text.ts";

/**
 * A run of capitals standing on its own.
 *
 * Requiring two adjacent capitals and forbidding an adjacent letter or digit is
 * what keeps chemical formulas out: NaCl has no two capitals in a row, and CO2
 * and NH3 are followed by one. Both are formulas, not abbreviations, and neither
 * is something an author is expected to define.
 */
const ABBREVIATION = /(?<![A-Za-z0-9\-−–])([A-Z]{2,9})(?![A-Za-z0-9])/gu;

/** 化合物 II, Table IV — numbering, not an abbreviation. */
const ROMAN_NUMERAL = /^[IVXLCDM]+$/u;

/**
 * A heading set in capitals: every word in it would look like an abbreviation.
 *
 * Japanese text contains no lowercase Latin either, so kana and kanji have to
 * disqualify a paragraph too — otherwise this would skip the entire manuscript.
 */
const ALL_CAPS_HEADING = /^[^a-z\p{sc=Hiragana}\p{sc=Katakana}\p{sc=Han}]*$/u;

const OPEN_PAREN_BEFORE = /[(（]\s*$/u;
const CLOSE_PAREN_AFTER = /^\s*[)）]/u;
/** 「NMR (nuclear magnetic resonance)」 — the expansion trails the abbreviation. */
const EXPANSION_AFTER = /^\s*[(（][^)）]{4,}[)）]/u;

const KNOWN = new Set(COMMON_ABBREVIATIONS.map((word) => word.toUpperCase()));

/**
 * Whether this occurrence spells the abbreviation out, either way round:
 *
 *   核磁気共鳴（NMR）を測定した      — expansion first, abbreviation in brackets
 *   NMR (nuclear magnetic resonance) — abbreviation first, expansion in brackets
 */
export function definesAbbreviation(text: string, start: number, end: number): boolean {
  const before = text.slice(0, start);
  const after = text.slice(end);
  if (OPEN_PAREN_BEFORE.test(before) && CLOSE_PAREN_AFTER.test(after)) {
    // A bare 「(NMR)」 at the head of a paragraph defines nothing; there has to be
    // an expansion in front of the bracket for this to count.
    return before.replace(OPEN_PAREN_BEFORE, "").trim().length >= 4;
  }
  return EXPANSION_AFTER.test(after);
}

export const undefinedAbbreviationRule: DocumentRule = {
  id: "undefined-abbreviation",
  category: "science",
  title: "略語の定義",
  kind: "document",
  run(paragraphs): Finding[] {
    interface Occurrence {
      readonly paragraphIndex: number;
      readonly start: number;
      readonly text: string;
    }
    /** abbreviation → where it first appears, and whether anywhere defines it. */
    const first = new Map<string, Occurrence>();
    const defined = new Set<string>();

    paragraphs.forEach((text, paragraphIndex) => {
      if (ALL_CAPS_HEADING.test(text)) return;
      for (const m of matchAll(ABBREVIATION, text)) {
        const word = m[1]!;
        if (KNOWN.has(word) || ROMAN_NUMERAL.test(word)) continue;
        const end = m.index + word.length;
        if (definesAbbreviation(text, m.index, end)) {
          defined.add(word);
          continue;
        }
        if (!first.has(word)) first.set(word, { paragraphIndex, start: m.index, text: word });
      }
    });

    const found: Finding[] = [];
    for (const [word, where] of first) {
      if (defined.has(word)) continue;
      found.push(
        finding(undefinedAbbreviationRule, {
          severity: "confirm",
          paragraphIndex: where.paragraphIndex,
          start: where.start,
          matched: where.text,
          message: `略語「${word}」が定義されずに使われています。初出で正式名称を示してください（例：「…（${word}）」）。`,
        }),
      );
    }
    return found;
  },
};

export const SCIENCE_RULES = [undefinedAbbreviationRule];
