/**
 * 2-(2) 図表関係 — 黄マーカー.
 *
 * The drawing-quality items (ChemDraw の矢印の長さ, least motion, 図のサイズ)
 * describe artwork, not text, so they are out of reach here. What is decidable:
 * caption punctuation, where the figure number goes relative to the sentence
 * period, and whether captions and in-text references line up.
 */
import type { DocumentRule, Finding, ParagraphRule } from "../types.ts";
import { finding } from "../types.ts";
import { LABEL_END } from "../labels.ts";
import { matchAll } from "../text.ts";

/** Caption-bearing labels, in the order journals normally number them. */
const LABELS = ["Figure", "Fig.", "Table", "Scheme", "Chart", "Equation", "Eq."] as const;

/**
 * Every spelling a label is written in, longest first so the alternation prefers
 * "Figures" over "Figure". Japanese manuscripts label their own figures 図1 /
 * 表1 / スキーム1, and a caption written that way was invisible to this rule
 * until those were added.
 */
const LATIN_LABEL_ALT =
  "Figures|Figure|Figs\\.|Fig\\.|Tables|Table|Schemes|Scheme|Charts|Chart|" +
  "Equations|Equation|Eqs\\.|Eq\\.";
const JA_LABEL_ALT = "図|表|スキーム";
const LABEL_ALT = `${LATIN_LABEL_ALT}|${JA_LABEL_ALT}`;

/** Plural labels ("Figures 1 and 2") only ever introduce a citation, never a caption. */
const PLURAL_LABEL = /^(?:Figures|Figs\.|Tables|Schemes|Charts|Equations|Eqs\.)$/u;

/** Labels written in Japanese, whose captions punctuate in Japanese too. */
const JAPANESE_LABEL = /^(?:図|表|スキーム)$/u;

/** Word marks an inline image with U+0001, which can sit in front of a caption. */
const CAPTION_START = new RegExp(
  `^[\\s\\u0001\\u0002]*(${LABEL_ALT})\\s*(\\d+)\\s*([.．:：]?)\\s*(.*)$`,
  "u",
);

/**
 * A number that continues a citation list: 「Figures 1 and 2」「Figs. 1–3」「図1，2」.
 * A dash-like separator means a range, so 1–3 stands for 1, 2 and 3.
 */
const REF_TAIL = /\s*(,|、|，|and|&|–|—|―|-|~|〜|から|および|と)\s*(\d+)/gu;
const RANGE_SEPARATOR = /^(?:[–—―\-~〜]|から)$/u;

/**
 * A citation in running text, with everything that follows its first number.
 *
 * Each script needs its own guard against a label glued to the back of a longer
 * word. For Latin that is any preceding letter ("SuperFigure 1"); for Japanese
 * it has to be a preceding *kanji* only — 「模式図1」 and 「発表1」 are compounds,
 * but 「を図1に示す」 is the ordinary way to cite one, and a guard against kana
 * would have thrown away nearly every Japanese citation there is.
 */
const INTEXT_REF = new RegExp(
  `((?<![A-Za-z])(?:${LATIN_LABEL_ALT})|(?<!\\p{sc=Han})(?:${JA_LABEL_ALT}))\\s*(\\d+)` +
    `((?:\\s*(?:,|、|，|and|&|–|—|―|-|~|〜|から|および|と)\\s*\\d+)*)`,
  "gu",
);

export interface CaptionInfo {
  readonly paragraphIndex: number;
  readonly label: string;
  readonly number: number;
  /** Text following the number, e.g. "X-ray crystal structure of 1." */
  readonly body: string;
  readonly separator: string;
  /** Offsets of the 「Figure 1」 head within the paragraph. */
  readonly headStart: number;
  readonly headEnd: number;
  /** That head exactly as written, spacing included, for locating it in Word. */
  readonly head: string;
}

/**
 * Text that continues a sentence rather than titling a figure.
 *
 * 「Figure 1 に示すように…」 and "Figure 1 shows the …" are body text that happens
 * to begin with a label. Reading them as captions used to cost twice: the figure
 * lost its only citation, and a phantom caption joined the numbering check.
 */
const RUNNING_TEXT = /^[\p{sc=Hiragana}a-z]/u;

/** 「図1，2に示す」 — a second number right after the first makes it a citation list. */
const CITATION_LIST = /^\s*(?:[、，,;；]|and\b|&|[–—―~〜]|から|および)\s*\d/u;

/** Parses a paragraph as a caption, or returns null when it is body text. */
export function parseCaption(text: string): Omit<CaptionInfo, "paragraphIndex"> | null {
  const m = CAPTION_START.exec(text);
  if (!m) return null;
  const label = m[1]!;
  if (PLURAL_LABEL.test(label)) return null;

  const separator = m[3]!;
  const body = m[4]!.trim();
  if (CITATION_LIST.test(`${separator}${body}`)) return null;
  // A separator settles it; without one, a lowercase word or a kana particle
  // after the number means the label is the subject of a sentence.
  if (separator.length === 0 && body.length > 0 && RUNNING_TEXT.test(body)) return null;

  const headStart = text.indexOf(label);
  const digits = m[2]!;
  const headEnd = text.indexOf(digits, headStart + label.length) + digits.length;
  return {
    label,
    number: Number(digits),
    separator,
    body,
    headStart,
    headEnd,
    head: text.slice(headStart, headEnd),
  };
}

/** One citation span, with every figure number it names. */
export interface IntextRef {
  /** Normalized label: 「Figs.」 and 「Figures」 both come back as 「Figure」. */
  readonly label: string;
  readonly numbers: readonly number[];
  readonly start: number;
  /** The span as written, e.g. "Figures 1 and 2". */
  readonly text: string;
}

/**
 * Citations in a paragraph. Ranges and lists are expanded, so a caption for
 * Figure 2 counts as cited by 「Figs. 1–3」.
 */
export function intextRefs(text: string): IntextRef[] {
  const refs: IntextRef[] = [];
  for (const m of matchAll(INTEXT_REF, text)) {
    const numbers = [Number(m[2])];
    for (const tail of matchAll(REF_TAIL, m[3] ?? "")) {
      const value = Number(tail[2]);
      const previous = numbers[numbers.length - 1]!;
      // A range wider than this is not a citation list — 「Table 1-100」 is more
      // likely a hyphenated identifier than a hundred referenced tables.
      if (RANGE_SEPARATOR.test(tail[1]!) && value > previous && value - previous <= 20) {
        for (let n = previous + 1; n <= value; n += 1) numbers.push(n);
      } else {
        numbers.push(value);
      }
    }
    refs.push({ label: normalizeLabel(m[1]!), numbers, start: m.index, text: m[0] });
  }
  return refs;
}

/**
 * 文末に括弧で図表番号を入れる際の括弧の位置.
 *
 *   （誤）・・・である．(Figure 1)
 *   （正）・・・である (Figure 1)．
 *
 * The reference belongs inside the sentence, so the terminator moves to the end.
 */
const PAREN_AFTER_PERIOD = new RegExp(
  `([。．.])\\s*(\\((?:${LABEL_ALT})[^)]*\\))\\s*([。．.]?)`,
  "gu",
);

export const figureParenPositionRule: ParagraphRule = {
  id: "figure-paren-position",
  category: "figure",
  title: "文末括弧（Figure 1）の位置",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const m of matchAll(PAREN_AFTER_PERIOD, text)) {
      // Already correct when a terminator follows the bracket too.
      if (m[3]) continue;
      const terminator = m[1]!;
      const replacement = ` ${m[2]}${terminator}`;
      found.push(
        finding(figureParenPositionRule, {
          severity: "fix",
          paragraphIndex: index,
          start: m.index,
          matched: m[0],
          replacement,
          message: `句点は図表番号の後ろへ：「${m[0]}」→「${replacement.trim()}」`,
        }),
      );
    }
    return found;
  },
};

/**
 * 図表番号の後のピリオド：説明文が続く場合は「Figure 1.」、続かない場合は不要。
 * また 図のキャプションの最後はピリオドで止める。
 */
export const captionPunctuationRule: ParagraphRule = {
  id: "caption-punctuation",
  category: "figure",
  title: "キャプションのピリオド",
  kind: "paragraph",
  run(text, index): Finding[] {
    const caption = parseCaption(text);
    if (!caption) return [];
    const found: Finding[] = [];
    const head = caption.head;
    // 「図1．」 is the Japanese caption's own full stop; insisting on the ASCII
    // period there would be an anglicism, not a correction.
    const period = JAPANESE_LABEL.test(caption.label) ? "．" : ".";
    const hasPeriod = /^[.．]$/u.test(caption.separator);

    if (caption.body.length > 0 && !hasPeriod) {
      const bodyStart = text.indexOf(caption.body, caption.headEnd);
      const matched = text.slice(caption.headStart, bodyStart).trimEnd();
      found.push(
        finding(captionPunctuationRule, {
          severity: "fix",
          paragraphIndex: index,
          start: caption.headStart,
          matched,
          replacement: `${head}${period}`,
          message: `説明文が続くので図表番号の後にピリオドを付けます：「${matched}」→「${head}${period}」`,
        }),
      );
    }

    if (caption.body.length === 0 && hasPeriod) {
      const matched = text.slice(caption.headStart).trimEnd();
      found.push(
        finding(captionPunctuationRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: caption.headStart,
          matched,
          replacement: head,
          message: `後ろに説明文がないのでピリオドは不要です：「${matched}」→「${head}」`,
        }),
      );
    }

    if (caption.body.length > 0 && !/[.．。]$/u.test(caption.body)) {
      // Anchor on the final word rather than the final character, so the
      // finding reads sensibly in the pane and locates unambiguously in Word.
      const lastWord = /(\S+)\s*$/u.exec(caption.body)?.[1] ?? caption.body;
      const start = text.lastIndexOf(lastWord);
      found.push(
        finding(captionPunctuationRule, {
          severity: "fix",
          paragraphIndex: index,
          start,
          matched: lastWord,
          replacement: `${lastWord}.`,
          message: `図表キャプションの最後はピリオドで止めます：「…${lastWord}」→「…${lastWord}.」`,
        }),
      );
    }

    return found;
  },
};

/**
 * 文中に図表番号を引用し対応させること — cross-checks the two sides:
 * a caption with no in-text reference, a reference with no caption, and a gap
 * in the numbering (which also covers 「登場する順番に付ける」 for figures).
 */
export const figureCrossReferenceRule: DocumentRule = {
  id: "figure-cross-reference",
  category: "figure",
  title: "図表番号の対応と連番",
  kind: "document",
  run(paragraphs): Finding[] {
    const captions: CaptionInfo[] = [];
    /** label → number → first paragraph where it is cited in running text. */
    const cited = new Map<string, Map<number, { paragraphIndex: number; start: number; text: string }>>();

    paragraphs.forEach((text, paragraphIndex) => {
      const caption = parseCaption(text);
      if (caption) captions.push({ ...caption, paragraphIndex });
      // A caption can cite its neighbours (「条件は Figure 2 と同じ」), so its text
      // is scanned too — minus its own head, which is the caption, not a citation.
      for (const ref of intextRefs(text)) {
        if (caption && ref.start < caption.headEnd) continue;
        if (!cited.has(ref.label)) cited.set(ref.label, new Map());
        const perLabel = cited.get(ref.label)!;
        for (const number of ref.numbers) {
          if (!perLabel.has(number)) {
            perLabel.set(number, { paragraphIndex, start: ref.start, text: ref.text });
          }
        }
      }
    });

    const found: Finding[] = [];

    // A caption that the text never points at. Raised as 確認 rather than 情報:
    // a figure nobody refers to is either dead weight or a missing sentence.
    for (const caption of captions) {
      const label = normalizeLabel(caption.label);
      if (cited.get(label)?.has(caption.number)) continue;
      const head = caption.head;
      found.push(
        finding(figureCrossReferenceRule, {
          severity: "confirm",
          paragraphIndex: caption.paragraphIndex,
          start: caption.headStart,
          matched: head,
          message: `${head} のキャプションはありますが、本文中で引用されていません。本文から「${head}」に言及してください。`,
        }),
      );
    }

    // A reference with no matching caption.
    const captionNumbers = new Map<string, Set<number>>();
    for (const caption of captions) {
      const label = normalizeLabel(caption.label);
      if (!captionNumbers.has(label)) captionNumbers.set(label, new Set());
      captionNumbers.get(label)!.add(caption.number);
    }
    // One citation span can name several numbers (「Figs. 1–3」), so the missing
    // ones are collected per span and reported once, not once per number.
    interface Missing {
      readonly where: { paragraphIndex: number; start: number; text: string };
      readonly label: string;
      readonly numbers: number[];
    }
    const missing = new Map<string, Missing>();
    for (const [label, perLabel] of cited) {
      for (const [number, where] of perLabel) {
        if (captionNumbers.get(label)?.has(number)) continue;
        const key = `${where.paragraphIndex}:${where.start}:${label}`;
        const entry = missing.get(key) ?? { where, label, numbers: [] };
        entry.numbers.push(number);
        missing.set(key, entry);
      }
    }
    for (const { where, label, numbers } of missing.values()) {
      const list = numbers.sort((a, b) => a - b).map((n) => `${label} ${n}`).join("、");
      found.push(
        finding(figureCrossReferenceRule, {
          severity: "note",
          paragraphIndex: where.paragraphIndex,
          start: where.start,
          matched: where.text,
          message: `${where.text} を引用していますが、${list} のキャプションが見つかりません。`,
        }),
      );
    }

    // 化合物番号は登場する順番に付ける — same logic applies to figures: the order
    // captions appear must match their numbering.
    const byLabel = new Map<string, CaptionInfo[]>();
    for (const caption of captions) {
      const label = normalizeLabel(caption.label);
      if (!byLabel.has(label)) byLabel.set(label, []);
      byLabel.get(label)!.push(caption);
    }
    for (const [label, list] of byLabel) {
      list.forEach((caption, i) => {
        if (caption.number === i + 1) return;
        found.push(
          finding(figureCrossReferenceRule, {
            severity: "confirm",
            paragraphIndex: caption.paragraphIndex,
            start: caption.headStart,
            matched: caption.head,
            message: `${label} の番号が登場順になっていません（${i + 1} 番目に ${caption.number} が登場）。`,
          }),
        );
      });
    }

    return found;
  },
};

/** Collapses every spelling of a label onto one name: Figs. と Figures は Figure。 */
export function normalizeLabel(label: string): string {
  if (/^Figs?\.$|^Figures?$/u.test(label)) return "Figure";
  if (/^Eqs?\.$|^Equations?$/u.test(label)) return "Equation";
  if (/^Tables?$/u.test(label)) return "Table";
  if (/^Schemes?$/u.test(label)) return "Scheme";
  if (/^Charts?$/u.test(label)) return "Chart";
  return label; // 図 / 表 / スキーム keep their own identity
}

/**
 * 化合物番号は登場する順番に付ける.
 *
 * Two things make this rule easy to get wrong, and both used to be wrong.
 *
 * **What counts as a mention.** A paper writes its compounds every which way:
 * 「化合物 5」, "compound 5", the series label 「5a」, the range 「1a–f」, and very
 * often the bare number 「5」 once the reader knows what is meant. Only the first
 * form used to be recognised. A bare digit cannot be told from a year or a
 * volume, so it is still not recognised — but the labels are, by asking
 * `ctx.compoundLabels`, which has already read the whole document for evidence.
 *
 * **What counts as out of order.** The old check counted 1, 2, 3… and reported
 * anything that broke the run, so a paper whose first *recognised* compound was
 * 5 got 「1 が来るべき位置に 5 が初出」 — an accusation about compounds 1 to 4,
 * which the rule simply had not seen. The checklist asks that numbers be
 * assigned **in order of appearance**, which is a statement about the numbers
 * relative to each other. So the run only has to ascend: 5, 6, 7 is fine, and
 * 5, 3 is not. Anything the rule cannot see costs it a detection, never a
 * false accusation.
 */
const COMPOUND_WORD = /(?:compounds?|化合物)\s*(\d{1,4})[a-z]?/giu;
const COMPOUND_LABEL = new RegExp(`(?<![A-Za-z0-9.])(\\d{1,4})[a-z]${LABEL_END}`, "gu");

export const compoundOrderRule: DocumentRule = {
  id: "compound-order",
  category: "figure",
  title: "化合物番号の登場順",
  kind: "document",
  run(paragraphs, ctx): Finding[] {
    interface Mention {
      readonly paragraphIndex: number;
      readonly start: number;
      readonly text: string;
      readonly number: number;
    }

    const mentions: Mention[] = [];
    paragraphs.forEach((text, paragraphIndex) => {
      for (const m of matchAll(COMPOUND_WORD, text)) {
        mentions.push({ paragraphIndex, start: m.index, text: m[0], number: Number(m[1]) });
      }
      for (const m of matchAll(COMPOUND_LABEL, text)) {
        // 「18d」 is a compound label only where the document treats it as one;
        // otherwise it is 18 days. `compoundLabels` is what decides.
        if (!ctx.compoundLabels.has(m[0])) continue;
        mentions.push({ paragraphIndex, start: m.index, text: m[0], number: Number(m[1]) });
      }
    });

    mentions.sort((a, b) => a.paragraphIndex - b.paragraphIndex || a.start - b.start);

    const first = new Map<number, Mention>();
    for (const mention of mentions) {
      if (!first.has(mention.number)) first.set(mention.number, mention);
    }

    const found: Finding[] = [];
    let highest = 0;
    // `first` keeps insertion order, which is document order after the sort.
    for (const [number, where] of first) {
      if (number > highest) {
        highest = number;
        continue;
      }
      found.push(
        finding(compoundOrderRule, {
          severity: "confirm",
          paragraphIndex: where.paragraphIndex,
          start: where.start,
          matched: where.text,
          message: `化合物番号は登場順に付けます（${highest} を先に出したあとで ${number} が初出）。`,
        }),
      );
    }
    return found;
  },
};

/** 文中に引用する図表番号は太字にしない / キャプションの番号は太字にする は書式判定なので office 層。 */
export const FIGURE_RULES = [
  figureParenPositionRule,
  captionPunctuationRule,
  figureCrossReferenceRule,
  compoundOrderRule,
];

export { LABELS, CAPTION_START, INTEXT_REF, JAPANESE_LABEL };
