// --- 段落そのものの書式 ----------------------------------------------------
//
// 「キャプションは中央揃えではなく図の左端に合わせる」 is about the paragraph, not a
// span inside it, so it cannot go through the probe/search/font path above.

/** A check that reads a property of the paragraph rather than of a range. */
interface ParagraphCheck {
  readonly id: string;
  readonly title: string;
  readonly category: Category;
  readonly severity: Finding["severity"];
  /** The span the finding points at, or null when the paragraph is not in scope. */
  readonly anchor: (text: string) => { readonly start: number; readonly text: string } | null;
  /** Paragraph properties to load. */
  readonly load: string;
  readonly verdict: (paragraph: Word.Paragraph) => string | null;
  readonly fix: (paragraph: Word.Paragraph) => void;
}

/** Office.js spells the enum in TitleCase; compare loosely so a fake can too. */
function isCentered(alignment: unknown): boolean {
  return typeof alignment === "string" && alignment.toLowerCase() === "centered";
}

const PARAGRAPH_CHECKS: readonly ParagraphCheck[] = [
  {
    id: "caption-alignment",
    category: "figure",
    title: "キャプションは中央揃えにしない",
    severity: "fix",
    anchor: (text) => {
      const caption = parseCaption(text);
      return caption === null ? null : { start: caption.headStart, text: caption.head };
    },
    load: "alignment",
    verdict: (paragraph) =>
      isCentered(paragraph.alignment)
        ? "キャプションが中央揃えです。図の左端に合わせます（左揃え）。"
        : null,
    fix: (paragraph) => {
      paragraph.alignment = "Left" as Word.Alignment;
    },
  },
];

/** The formatting checks as data, for the rule list in 「ルール設定」. */
export const FORMAT_CHECK_INFO: ReadonlyArray<{
  readonly id: string;
  readonly title: string;
  readonly category: Category;
}> = [...CHECKS, ...PARAGRAPH_CHECKS].map(({ id, title, category }) => ({ id, title, category }));

/**
 * Checks that stay silent because a stronger, enabled check already covers them.
 *
 * Exported so that "this rule is on but reports nothing" is explainable rather
 * than mysterious — the rule list says so, and a test holds the pairing.
 */
export function supersededFormatChecks(disabled: ReadonlySet<string>): string[] {
  return CHECKS.filter((c) => c.supersededBy !== undefined && !disabled.has(c.supersededBy)).map(
    (c) => c.id,
  );
}

function activeChecks(disabled: ReadonlySet<string>): FormatCheck[] {
  const superseded = new Set(supersededFormatChecks(disabled));
  return CHECKS.filter((c) => !disabled.has(c.id) && !superseded.has(c.id));
}

/** Applies the fix belonging to a formatting finding. */
export function applyFormatFix(ruleId: string, font: Word.Font, latinFont: string): boolean {
  const check = CHECKS.find((c) => c.id === ruleId);
  if (!check?.fix) return false;
  check.fix(font, latinFont);
  return true;
}

export function isFormatCheckId(ruleId: string): boolean {
  return CHECKS.some((c) => c.id === ruleId);
}

export function isParagraphCheckId(ruleId: string): boolean {
  return PARAGRAPH_CHECKS.some((c) => c.id === ruleId);
}

/** Applies the fix belonging to a paragraph-level finding. */
export function applyParagraphFix(ruleId: string, paragraph: Word.Paragraph): boolean {
  const check = PARAGRAPH_CHECKS.find((c) => c.id === ruleId);
  if (!check) return false;
  check.fix(paragraph);
  return true;
}

/**
 * Runs the paragraph-level checks. One `context.sync()` for the whole document:
 * every paragraph in scope has its properties requested before the first wait.
 */
export async function runParagraphChecks(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
  disabled: ReadonlySet<string> = new Set(),
): Promise<Finding[]> {
  interface Pending {
    readonly check: ParagraphCheck;
    readonly paragraph: Word.Paragraph;
    readonly paragraphIndex: number;
    readonly anchor: { readonly start: number; readonly text: string };
  }

  const checks = PARAGRAPH_CHECKS.filter((c) => !disabled.has(c.id));
  if (checks.length === 0) return [];

  const pending: Pending[] = [];
  paragraphTexts.forEach((text, paragraphIndex) => {
    const paragraph = paragraphs[paragraphIndex];
    if (!paragraph) return;
    for (const check of checks) {
      const anchor = check.anchor(text);
      if (!anchor) continue;
      paragraph.load(check.load);
      pending.push({ check, paragraph, paragraphIndex, anchor });
    }
  });

  if (pending.length === 0) return [];
  await context.sync();

  const findings: Finding[] = [];
  for (const item of pending) {
    const message = item.check.verdict(item.paragraph);
    if (!message) continue;
    findings.push({
      ruleId: item.check.id,
      category: item.check.category,
      severity: item.check.severity,
      paragraphIndex: item.paragraphIndex,
      start: item.anchor.start,
      end: item.anchor.start + item.anchor.text.length,
      matched: item.anchor.text,
      message,
    });
  }
  return findings;
}

/**
 * Runs every formatting check over the given paragraphs.
 *
 * All probes across all checks are searched in one batch, then all fonts are
 * loaded in a second batch, so the whole pass costs two `context.sync()` calls
 * regardless of how many findings there are.
 */
export async function runFormatChecks(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
  disabled: ReadonlySet<string> = new Set(),
  labels: ReadonlySet<string> = new Set(),
): Promise<Finding[]> {
  interface Pending {
    readonly check: FormatCheck;
    readonly probe: Probe;
    readonly paragraphIndex: number;
    readonly ordinal: number;
    readonly results: Word.RangeCollection;
  }

  const pending: Pending[] = [];
  const checks = activeChecks(disabled);

  paragraphTexts.forEach((text, paragraphIndex) => {
    const paragraph = paragraphs[paragraphIndex];
    if (!paragraph) return;
    for (const check of checks) {
      for (const probe of check.probe(text, labels)) {
        const term = searchTermFor(probe.text);
        if (term.length === 0) continue;
        const ordinal = occurrenceIndex(text, probe.text, probe.start);
        if (ordinal < 0) continue;
        const results = paragraph.search(term, EXACT);
        results.load("items");
        pending.push({ check, probe, paragraphIndex, ordinal, results });
      }
    }
  });

  if (pending.length === 0) return [];
  await context.sync();

  const resolved: Array<{ pending: Pending; range: Word.Range }> = [];
  for (const item of pending) {
    const range = item.results.items[item.ordinal];
    if (!range) continue;
    range.font.load(item.check.load);
    resolved.push({ pending: item, range });
  }

  if (resolved.length === 0) return [];
  await context.sync();

  const findings: Finding[] = [];
  for (const { pending: item, range } of resolved) {
    const message = item.check.verdict(range.font, item.probe);
    if (!message) continue;
    const replacement = item.check.replacement?.(item.probe);
    findings.push({
      ruleId: item.check.id,
      category: item.check.category,
      severity: item.check.severity,
      paragraphIndex: item.paragraphIndex,
      start: item.probe.start,
      end: item.probe.end,
      matched: item.probe.text,
      ...(replacement === undefined ? {} : { replacement }),
      message,
    });
  }
  return findings;
}

/**
 * 上付きの数字は引用番号なので、和文との間に空白は要らない.
 *
 * 「である14，」 is a citation and 「その14件」 is the number fourteen; the text is the
 * same shape and only the formatting tells them apart. So 「和文と英数字の間隔」
 * reports both, and this pass — the only place that can see superscripts — takes
 * the citations back out.
 *
 * Only findings that touch digits are looked up, so a document with no citation
 * numbers costs nothing beyond the check for them.
 */
export async function dropSuperscriptCitations(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
  findings: readonly Finding[],
): Promise<Finding[]> {
  interface Pending {
    readonly finding: Finding;
    readonly ordinal: number;
    readonly results: Word.RangeCollection;
  }

  const pending: Pending[] = [];
  for (const item of findings) {
    if (item.ruleId !== SPACING_RULE_ID) continue;
    const text = paragraphTexts[item.paragraphIndex];
    const paragraph = paragraphs[item.paragraphIndex];
    if (text === undefined || !paragraph) continue;

    const digits = digitRunFor(text, item);
    if (!digits) continue;
    const term = searchTermFor(digits.text);
    if (term.length === 0) continue;
    const ordinal = occurrenceIndex(text, digits.text, digits.start);
    if (ordinal < 0) continue;

    const results = paragraph.search(term, EXACT);
    results.load("items");
    pending.push({ finding: item, ordinal, results });
  }

  if (pending.length === 0) return [...findings];
  await context.sync();

  const resolved: Array<{ finding: Finding; range: Word.Range }> = [];
  for (const item of pending) {
    const range = item.results.items[item.ordinal];
    if (!range) continue;
    range.font.load("superscript");
    resolved.push({ finding: item.finding, range });
  }

  if (resolved.length === 0) return [...findings];
  await context.sync();

  const citations = new Set<Finding>();
  for (const { finding: item, range } of resolved) {
    if (range.font.superscript) citations.add(item);
  }
  return findings.filter((item) => !citations.has(item));
}

/** The Latin letter in a 「p共役」-shaped finding, with where it sits. */
function loneLetterOf(item: Finding): { text: string; start: number } | null {
  const match = /[A-Za-z]/u.exec(item.matched);
  return match === null ? null : { text: match[0], start: item.start + match.index };
}

/**
 * Takes back the 「ギリシャ文字と和文の間隔」 findings whose letter is not Symbol.
 *
 * The rule offers every lone letter beside 和文, because after
 * 「ギリシャ文字は Symbol フォント」 has run, a π *is* an ordinary 「p」 in the text and
 * no pattern can tell it from an English one. Here — the only place that can see
 * fonts — the ones that are really Latin are dropped, so 「T = 298 Kにおける」 stays
 * quiet while 「p共役」 does not.
 *
 * Findings on real Greek characters never reach the search and are kept as they
 * are. A host that cannot resolve the range keeps the finding too: suggesting a
 * space that was not needed is a smaller harm than silently losing the one case
 * this exists for.
 */
export async function dropNonSymbolLetters(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
  findings: readonly Finding[],
): Promise<Finding[]> {
  interface Pending {
    readonly finding: Finding;
    readonly ordinal: number;
    readonly results: Word.RangeCollection;
  }

  const pending: Pending[] = [];
  for (const item of findings) {
    if (item.ruleId !== greekSpacingRule.id) continue;
    const letter = loneLetterOf(item);
    if (!letter) continue; // 本物のギリシャ文字。フォントを見るまでもない。

    const text = paragraphTexts[item.paragraphIndex];
    const paragraph = paragraphs[item.paragraphIndex];
    if (text === undefined || !paragraph) continue;

    const term = searchTermFor(letter.text);
    if (term.length === 0) continue;
    const ordinal = occurrenceIndex(text, letter.text, letter.start);
    if (ordinal < 0) continue;

    const results = paragraph.search(term, EXACT);
    results.load("items");
    pending.push({ finding: item, ordinal, results });
  }

  if (pending.length === 0) return [...findings];
  await context.sync();

  const resolved: Array<{ finding: Finding; range: Word.Range }> = [];
  for (const item of pending) {
    const range = item.results.items[item.ordinal];
    if (!range) continue;
    range.font.load("name");
    resolved.push({ finding: item.finding, range });
  }

  if (resolved.length === 0) return [...findings];
  await context.sync();

  const latin = new Set<Finding>();
  for (const { finding: item, range } of resolved) {
    if (range.font.name !== SYMBOL_FONT) latin.add(item);
  }
  return findings.filter((item) => !latin.has(item));
}

export { preferredLatinFont };
