/* global Office */
/**
 * Ribbon command runtime. These functions run in a hidden runtime when the
 * Document Corrector custom-tab buttons are clicked (Action xsi:type="ExecuteFunction"
 * in the manifest). They cannot touch the task-pane DOM, so they use default
 * options and rely on the visible document change as feedback.
 */
import * as actions from "../office/actions.ts";
import { DEFAULT_OPTIONS } from "../office/actions.ts";

type CommandEvent = { completed: () => void };

/** Runs an action, always completing the ribbon event even on failure. */
function command(handler: () => Promise<unknown>): (event: CommandEvent) => void {
  return (event: CommandEvent) => {
    handler()
      .catch((error: unknown) => {
        // eslint-disable-next-line no-console
        console.error("Document Corrector command failed:", error);
      })
      .finally(() => event.completed());
  };
}

// This runtime can only ever paint spaces, so that is all it undoes — clearing
// the whole body would take the author's own marker with it.
const clearHighlights = command(() => actions.clearHighlights(DEFAULT_OPTIONS, { spaces: true }));

Office.onReady(() => {
  Office.actions.associate("clearHighlights", clearHighlights);
});
